    out.put("NafuhrBloodhammer", new NpcScripts.Entry(
        "NafuhrBloodhammer",
        "NPC RavensDust/NafuhrBloodhammer.cpp",
        "NafuhrBloodhammerNPC",
        "InitTalk\n\nBegin\n\"\"\nIF (Gold < 2000 )\n\tConversation\n\tINTL(\"${npc.cpp.intl.5570}\")\n\tBREAK\nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.5571}\")\nENDIF\t\n\nCommand2(INTL(\"${npc.cpp.intl.3694}\"),INTL(\"${npc.cpp.intl.485}\"))\nINTL(\"${npc.cpp.intl.5572}\")\n\nCommand3(INTL(\"${npc.cpp.intl.489}\"),INTL(\"${npc.cpp.intl.487}\"),INTL(\"${npc.cpp.intl.488}\"))\nINTL( 5573, \"I am the village's blacksmith. Although I know how to forge weapons, I leave this in the expert hands of \"\n\"\\\"Rhodar\\\" \\\"Heatforge\\\". My speciality is crafting strong and durable armors.\") \n\nCommand(INTL(\"${npc.cpp.intl.5574}\"))\nINTL( 5575, \"You look somewhat surprised that dwarven blood runs freely through my veins. \"\n\"I had a \\\"great\\\" \\\"grandfather\\\" who was a dwarf while his wife was human.\")   \t  \n\nCommand2(INTL(\"${npc.cpp.intl.5576}\"),INTL(\"${npc.cpp.intl.5577}\"))\nINTL(\"${npc.cpp.intl.5578}\")\n\t  \t  \t  \nCommand(INTL(\"${npc.cpp.intl.5579}\"))\nINTL( 5580, \"The name was Moridhar Rumblehill. He was an awesome warrior who could not \"\n\"be bested in one-on-one combat. In fact, he even fought the powerful dragons of Firesky. Alas, \"\n\"he never learn to retreat and eventually ended up crushed by a \\\"dragon\\\".\")  \n\nCommand2(INTL(\"${npc.cpp.intl.5581}\"),INTL(\"${npc.cpp.intl.5582}\"))\nINTL(\"${npc.cpp.intl.5583}\") \n\nCommand2(INTL(\"${npc.cpp.intl.5584}\"),INTL(\"${npc.cpp.intl.5585}\"))\nINTL(\"${npc.cpp.intl.5586}\")\n\nCmdAND(INTL(\"${npc.cpp.intl.1367}\"),INTL(\"${npc.cpp.intl.2005}\"))\n\"\"\nIF ((CheckItem(__OBJ_TIGER_TOOTH) >= 1) && (CheckFlag(__FLAG_SIGFRIED_SCAM) == 2))\n\tConversation\n\tINTL( 5587, \"The dragon tooth was a tiger's tooth in reality? I knew it. It's so small, even a \"\n\t\"baby wyrm has bigger teeth!\")\nELSEIF ((CheckItem(__OBJ_DRAGON_TOOTH) >= 1) && (CheckFlag(__FLAG_SIGFRIED_SCAM) >= 1))\n\tConversation\n\tINTL(\"${npc.cpp.intl.5588}\")  \nELSEIF (CheckItem(__OBJ_DRAGON_TOOTH) >= 1)\n\tConversation\n\tINTL(\"${npc.cpp.intl.5589}\")\n\tGiveFlag(__FLAG_SIGFRIED_SCAM,1)\nELSE\n\tConversation\n\tINTL( 5590, \"A dragon tooth? I don't have any but I know when I see one. \\\"Moridhar\\\" \\\"Rumblehill\\\", \"\n\t\"my great grandfather was a dragon slayer.\") \nENDIF\n\nCommand(INTL(\"${npc.cpp.intl.10429}\")) \n\"\"\nIF ((CheckItem(__OBJ_TIGER_TOOTH) >= 1) && (CheckFlag(__FLAG_SIGFRIED_SCAM) == 2))\n\tConversation\n\tINTL( 5587, \"The dragon tooth was a tiger's tooth in reality? I knew it. It's so small, even a \"\n\t\"baby wyrm has bigger teeth!\")\nELSEIF ((CheckItem(__OBJ_DRAGON_TOOTH) >= 1) && (CheckFlag(__FLAG_SIGFRIED_SCAM) >= 1))\n\tConversation\n\tINTL(\"${npc.cpp.intl.5588}\")  \nELSEIF (CheckItem(__OBJ_DRAGON_TOOTH) >= 1)\n\tConversation\n\tINTL(\"${npc.cpp.intl.5589}\")\n\tGiveFlag(__FLAG_SIGFRIED_SCAM,1)\nELSE\n\tConversation\n\tINTL( 5590, \"A dragon tooth? I don't have any but I know when I see one. \\\"Moridhar\\\" \\\"Rumblehill\\\", \"\n\t\"my great grandfather was a dragon slayer.\") \nENDIF\n\n\nCommand(INTL(\"${npc.cpp.intl.1367}\"))\nINTL( 7923, \"The dragons are fearsome creatures. They have razon-sharp talons, \\\"teeth\\\" that can bite \"\n\"through the strongest armors and some are even rumored to breathe fire! Fortunately, most of the \" \n\"evil dragons have mysteriously disappeared from Althea.\")\n\nCommand3(INTL(\"${npc.cpp.intl.1037}\"),INTL(\"${npc.cpp.intl.5110}\"),INTL(\"${npc.cpp.intl.2183}\"))\nINTL( 5591, \"Even though Murmuntag, Vuntertag and Guntertag are on the right side, they are still orcs \"\n\"and cannot be trusted. They will fight on your side (or against you) for a pouch of coins \"\n\"and a bread crust.\")\n\nCommand(INTL(\"${npc.cpp.intl.5592}\"))\nINTL(\"${npc.cpp.intl.5593}\") \n\nCommand(INTL(\"${npc.cpp.intl.744}\"))\nINTL( 5594, \"Orcs *cannot* be trusted. Incidentally, Raven's Dust is plagued by an orc campment located \"\n\"somewhere in the north. They have battle siege weapons that could do severe damages to our \"\n\"castle but fortunately for us, they are so heavy that even the orcish brutes cannot bring them \"\n\"within range.\") \n\nCommand2(INTL(\"${npc.cpp.intl.1304}\"),INTL(\"${npc.cpp.intl.916}\"))\nINTL(\"${npc.cpp.intl.5595}\")\nCreateItemList\n   AddBuyItem( 700,   __OBJ_RED_CAPE )\n\tAddBuyItem( 1086,  __OBJ_STUDDED_LEATHER_BELT )\n   AddBuyItem( 1402,  __OBJ_STUDDED_LEATHER_GLOVES )\n   AddBuyItem( 1510,  __OBJ_STUDDED_LEATHER_HELMET )\n   AddBuyItem( 1579,  __OBJ_STUDDED_LEATHER_PANTS )\n   AddBuyItem( 1372,  __OBJ_STUDDED_LEATHER_BOOTS )\n   AddBuyItem( 4538,  __OBJ_STUDDED_LEATHER_ARMOR )\n\n   AddBuyItem( 2308, __OBJ_RINGMAIL_GIRDLE )\n   AddBuyItem( 10039, __OBJ_RINGMAIL_ARMOR )\n   AddBuyItem( 3015, __OBJ_RINGMAIL_GAUNTLETS ) \n   AddBuyItem( 3258, __OBJ_RINGMAIL_HELMET )\n   AddBuyItem( 3413, __OBJ_RINGMAIL_LEGGINGS )\n   AddBuyItem( 2949, __OBJ_RINGMAIL_BOOTS ) \n\n\tAddBuyItem( 4694,  __OBJ_CHAINMAIL_GIRDLE )\n   AddBuyItem( 20777,  __OBJ_CHAINMAIL )\n   AddBuyItem( 6165,  __OBJ_CHAINMAIL_GLOVES )\n   AddBuyItem( 6670,  __OBJ_CHAINMAIL_COIF )\n   AddBuyItem( 6992,  __OBJ_CHAINMAIL_LEGGINGS )\n   AddBuyItem( 6072, __OBJ_CHAINMAIL_BOOTS) \n  \n\tAddBuyItem( 7389,  __OBJ_ROUND_SHIELD )\n\tAddBuyItem( 25990, __OBJ_LARGE_SHIELD )\n\nSendBuyItemList\n\nCommand(INTL(\"${npc.cpp.intl.1306}\"))\nINTL(\"${npc.cpp.intl.1307}\")\nCreateItemList\n    AddSellItem( ARMOR, 0, 100000 )\n    AddSellItem( MAGIC | ARMOR, 0, 100000 )\n    AddSellItem( JEWEL | ARMOR, 0, 100000 )\n    AddSellItem( MAGIC | JEWEL | ARMOR, 0, 100000 )\n\nSendSellItemList(INTL(\"${npc.cpp.intl.5596}\")) \n\nCommand(INTL(\"${npc.cpp.intl.3918}\"))\n\"\"\nIF (CheckFlag(__QUEST_VISITOR_SPOTTED) < 2)\n\tConversation\n\tINTL(\"${npc.cpp.intl.5597}\")\nELSEIF (CheckFlag(__QUEST_VISITOR_SPOTTED) == 2)\n\tConversation\n\tINTL( 5598, \"Ahh yes, it would seem you just missed him. Quite a strange man that was, I can tell you. He seemed \"\n\t\"rather in a hurry to leave town. I would assume that he was heading to Boreas' shop, so if you hurry, \"\n\t\"you might still catch up with him.\")\n\tGiveFlag(__QUEST_VISITOR_SPOTTED, 3)\nELSEIF (CheckFlag(__QUEST_VISITOR_SPOTTED) >= 3)\n\tConversation\n\tINTL(\"${npc.cpp.intl.5599}\")\nENDIF\t\n\nCommand3(INTL(\"${npc.cpp.intl.518}\"),INTL(\"${npc.cpp.intl.517}\"),INTL(\"${npc.cpp.intl.519}\"))\nINTL(\"${npc.cpp.intl.5600}\") BREAK\n\nDefault\nINTL(\"${npc.cpp.intl.4012}\")\n\nEndTalk",
        Map.of()));
    out.put("NamelessBard", new NpcScripts.Entry(
        "NamelessBard",
        "NPC AddOn/NamelessBard.cpp",
        "NamelessBardNPC",
        "InitTalk\n\nBegin\n\"\"\nIF(CheckFlag(__FLAG_ADDON_STORYLINE_PROGRESS) < 29)\n\tConversation\n\tINTL(\"${npc.cpp.intl.12428}\")\n\tPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.12429}\"))\n\tBREAK\nELSEIF(CheckFlag(__FLAG_ADDON_STORYLINE_PROGRESS) == 29)\n\tConversation\n\tINTL(\"${npc.cpp.intl.12430}\")\nELSEIF(CheckFlag(__FLAG_ADDON_STORYLINE_PROGRESS) < 32)\n\tConversation\n\tINTL( 12431, \"In a tree you will find wisdom, in a fountain, knowledge. Where wisdom and knowledge converge, the \"\n\t\"answers you seek will emerge.\")\nELSEIF((CheckFlag(__FLAG_ADDON_STORYLINE_PROGRESS) == 32)||(CheckFlag(__FLAG_ADDON_STORYLINE_PROGRESS) == 33))\n\tConversation\n\tINTL( 12432, \"What you have found is the word of power that opens the great gates of tremendous evil. They rest \"\n\t\"near the northernmost place in this land. To reach it, you will need to travel through darkness. Rest \"\n\t\"assured that if the Waters of Knowledge did not provide all the answers you seek, the one who dwells \"\n\t\"past those gates surely shall. This is your \\\"cursssse\\\".\")\n\tGiveFlag(__FLAG_ADDON_STORYLINE_PROGRESS, 33)\nELSE\n\tConversation\n\tINTL( 12433, \"I too was of the chosen... They came and offered us the forbidden... We refused and still we prayed to them... \"\n\t\"We dedicated our little life to their heaven... And they came and offered us the forsaken... Still we refused \"\n\t\"and we repented... Death came and cursed us of our lament... He slew all of us and in our amend... We swear that \"\n\t\"one day we will be avenged.\")\nENDIF\n\nCommand(INTL(\"${npc.cpp.intl.12434}\"))\n\"\"\nIF(CheckFlag(__FLAG_ADDON_STORYLINE_PROGRESS) == 29)\n\tConversation\n\tINTL(\"${npc.cpp.intl.12435}\")\nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.1864}\")\nENDIF\n\nCommand(INTL(\"${npc.cpp.intl.12436}\"))\n\"\"\nIF(CheckFlag(__FLAG_ADDON_STORYLINE_PROGRESS) == 29)\n\tConversation\n\tINTL(\"${npc.cpp.intl.12437}\")\nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.1864}\")\nENDIF\n\nCommand(INTL(\"${npc.cpp.intl.12438}\"))\n\"\"\nIF(CheckFlag(__FLAG_ADDON_STORYLINE_PROGRESS) == 29)\n\tConversation\n\tINTL( 12439, \"In a tree you will find wisdom, in a fountain, knowledge. Where wisdom and knowledge converge, the \"\n\t\"answers you seek will emerge.\")\n\tGiveFlag(__FLAG_ADDON_STORYLINE_PROGRESS, 30)\nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.1864}\")\nENDIF\n\nCommand(INTL(\"${npc.cpp.intl.12440}\"))\n\"\"\nIF(CheckFlag(__FLAG_ADDON_STORYLINE_PROGRESS) == 33)\n\tConversation\n\tINTL( 12441, \"I too was of the chosen... They came and offered us the forbidden... We refused and still we prayed to them... \"\n\t\"We dedicated our little life to their heaven... And they came and offered us the forsaken... Still we refused \"\n\t\"and we repented... Death came and cursed us of our lament... He slew all of us and in our amend... We swear that \"\n\t\"one day we will be avenged.\")\nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.1864}\")\nENDIF\n\nCommand5(INTL(\"${npc.cpp.intl.519}\"), INTL(\"${npc.cpp.intl.518}\"), INTL(\"${npc.cpp.intl.520}\"), INTL(\"${npc.cpp.intl.517}\"), INTL(\"${npc.cpp.intl.521}\"))\nINTL(\"${npc.cpp.intl.1864}\")\nBREAK\n\nDefault\nINTL(\"${npc.cpp.intl.1864}\")\n\nEndTalk",
        Map.of()));
