    out.put("SamilAlgder", new NpcScripts.Entry(
        "SamilAlgder",
        "NPC WindHowl/SamilAlgder.cpp",
        "SamilAlgderNPC",
        "InitTalk\n\nBegin\nINTL(\"${npc.cpp.intl.2683}\")\n\nCommand2(INTL(\"${npc.cpp.intl.483}\"),INTL(\"${npc.cpp.intl.485}\"))\nINTL(\"${npc.cpp.intl.2684}\")\n\nCommand3(INTL(\"${npc.cpp.intl.489}\"),INTL(\"${npc.cpp.intl.488}\"),INTL(\"${npc.cpp.intl.487}\"))\nINTL( 2685, \"My work, if it can be called that, is to follow the path set by \\\"Artherk\\\". \"\n\"I also have the task to bless our \\\"troops\\\" before they go into \"\n\" a confrontation, and to attend to their wounds when they come back.\")\n\nCommand3(INTL(\"${npc.cpp.intl.509}\"),INTL(\"${npc.cpp.intl.510}\"),INTL(\"${npc.cpp.intl.511}\"))\nINTL( 2686, \"Balork cursed you, you say? I'm sorry to hear that. If \\\"Annabelle\\\" the \"\n\"Blessed One was still here, she might be able to help you. But she's long \"\n\"gone, now. I hear a troll took her away to feast upon her.\") \n\nCommand(INTL(\"${npc.cpp.intl.523}\"))\nINTL( 2687, \"I knew her well, that Annabelle. Lovelier than an Elf--not that I know \"\n\"what Elves look like, they left this world a long, long time ago. But yes, \"\n\"you'd love to meet her...\")\n\nCommand(INTL(\"${npc.cpp.intl.2688}\"))\nINTL( 2689, \"Yes, we have a rather big army here in Windhowl, but we need all the troops \"\n\"we can find, for the \\\"goblins\\\" are relentless in their assaults. \"\n\"As a result, our troops need godly blessing before they go into combat, to help them \"\n\"fight longer and harder.\")\n\nCommand(INTL(\"${npc.cpp.intl.539}\"))\nINTL( 2690, \"The goblins are becoming increasingly deadly nowadays. I know not by what \"\n\"sadistic means they have accomplished it, but some of them have been seen \"\n\"wielding magical weapons!\")\n\nCommand(INTL(\"${npc.cpp.intl.2691}\"))\nINTL(\"${npc.cpp.intl.2692}\")\n\nCommand(INTL(\"${npc.cpp.intl.2693}\"))\nINTL(\"${npc.cpp.intl.2694}\")\n\nCommand(INTL(\"${npc.cpp.intl.2695}\"))\nINTL( 2696, \"I spend most of my time with the troops, but another priest will gladly \"\n\"help you.\")\n\nCommand(INTL(\"${npc.cpp.intl.1243}\"))\nINTL( 2697, \"Artherk is a kind and just god. I would follow him beyond the edge of the world \"\n\"if I had to.\")\n\nCommand(INTL(\"${npc.cpp.intl.746}\"))\nINTL( 2698, \"Druids can be very powerful, but they don't follow the true path of good. \"\n\"I do not dislike their ways, but I'd rather become a great priest.\")\n\nCommand5(INTL(\"${npc.cpp.intl.518}\"),INTL(\"${npc.cpp.intl.517}\"),INTL(\"${npc.cpp.intl.519}\"),INTL(\"${npc.cpp.intl.521}\"),INTL(\"${npc.cpp.intl.520}\"))\nINTL(\"${npc.cpp.intl.2699}\") BREAK\n\nDefault\nINTL(\"${npc.cpp.intl.2220}\")\n\nEndTalk",
        Map.of()));
    out.put("Samuel", new NpcScripts.Entry(
        "Samuel",
        "NPC RavensDust/Samuel.cpp",
        "SamuelNPC",
        "InitTalk\n\nBegin\nINTL(\"${npc.cpp.intl.5721}\")\n\nCommand2(INTL(\"${npc.cpp.intl.2034}\"),INTL(\"${npc.cpp.intl.2035}\"))\nINTL(\"${npc.cpp.intl.5722}\")\n\nCommand2(INTL(\"${npc.cpp.intl.3694}\"),INTL(\"${npc.cpp.intl.485}\"))\nINTL(\"${npc.cpp.intl.5723}\")\n\nCommand(INTL(\"${npc.cpp.intl.5726}\"))\nINTL(\"${npc.cpp.intl.5727}\")\n\nCommand(INTL(\"${npc.cpp.intl.5724}\"))\nINTL( 5725, \"I should have you thrown out of the castle or even in the \"\n\"\\\"prison\\\" for your impoliteness!\")\n\nCommand3(INTL(\"${npc.cpp.intl.489}\"),INTL(\"${npc.cpp.intl.487}\"),INTL(\"${npc.cpp.intl.488}\"))\nINTL(\"${npc.cpp.intl.5728}\")\n\nCommand(INTL(\"${npc.cpp.intl.1072}\"))\nINTL(\"${npc.cpp.intl.5729}\")\n\nCommand(INTL(\"${npc.cpp.intl.754}\"))\nINTL(\"${npc.cpp.intl.5730}\")\n\nCommand(INTL(\"${npc.cpp.intl.3918}\"))\nINTL( 5731, \"We don't get any unusual visitors in the castle! Well, now that you mention it, you look \"\n\"rather strange.\")\n\nCommand(INTL(\"${npc.cpp.intl.537}\"))\nINTL(\"${npc.cpp.intl.5732}\")\n\nCommand(INTL(\"${npc.cpp.intl.4131}\"))\nINTL( 5733, \"The prison under the Castle is no longer in use. Dark creatures led by a malevolent being \"\n\"that goes by the name of \\\"Death\\\" \\\"Jester\\\" have taken over. We thought it was easier to \"\n\"simply condemn the prison rather than attempting to fight the de.. Hmmmm. I mean them...\")\n\nCommand(INTL(\"${npc.cpp.intl.5734}\"))\n\"\"\nIF (CheckFlag(__QUEST_FLAG_DEATH_JESTER_DONE) == 1)\n\tConversation\n   INTL( 5735, \"You have already helped us. However, you should know that it is \"\n   \"futile to fight the dead. The dark soul of the Death Jester simply \"\n   \"have to enter another one of the many skeletal corpses in the dungeon \"\n   \"to revive once more to trouble our nights.\")\nELSEIF (CheckFlag(__QUEST_FLAG_KILLED_DEATH_JESTER) == 0)\n   IF (CheckItem(__OBJ_DEATH_JESTER_SKULL) >= 1)\n      Conversation\n      INTL( 5736, \"You do have its filthy skull but you did not vanquish the foe \"\n      \"by yourself. Therefore, you are not worthy of being rewarded!\") \n\t\t;int nNumSkulls = CheckItem(__OBJ_DEATH_JESTER_SKULL);\n      FOR(0, nNumSkulls )\n         TakeItem(__OBJ_DEATH_JESTER_SKULL)\n      ENDFOR\n   ELSE\n      Conversation\n      INTL( 5737, \"Sometimes, we can hear its horrible wail of despair throughout the \"\n      \"entire Castle of Theodore XIII. If you could bring back its skull \"\n      \"as the proof that you vanquished this terrible foe, I shall \"\n      \"reward you greatly for the few moments of peace it will provide us.\")\n   ENDIF\nELSE\n   IF (CheckItem(__OBJ_DEATH_JESTER_SKULL) == 0)\n      Conversation\n      INTL( 5738, \"You do not even have the skull. Get back down there and finish \"\n\t   \"it off!\")\n   ELSE\n\t\t;int nNumSkulls = CheckItem(__OBJ_DEATH_JESTER_SKULL);\n      FOR(0, nNumSkulls )            \n         TakeItem(__OBJ_DEATH_JESTER_SKULL) \n      ENDFOR\n      Conversation\n      INTL( 5739, \"You have defeated the Death Jester and brought back its ugly \"\n      \"skeleton head? I must admit that I misjudged your skills at first, \"\n      \"my friend. Good. Take this \\\"scarab\\\" \\\"protector\\\" and wear it \"\n      \"around your waist. {You} {have} {been} {awarded} {30000} \"\n       \"{experience} {points.}\")\n      GiveItem(__OBJ_SCARAB_PROTECTOR)     \n      GiveXP(30000)\n      RemFlag(__QUEST_FLAG_KILLED_DEATH_JESTER)\n      GiveFlag(__QUEST_FLAG_DEATH_JESTER_DONE,1)\n   ENDIF\nENDIF\n \nCmdAND(INTL(\"${npc.cpp.intl.5038}\"),INTL(\"${npc.cpp.intl.4648}\"))\n\"\"\nIF (CheckFlag(__QUEST_WAX_APPLE) == 0)\n   Conversation\n   INTL( 5740, \"You want an apple made of wax? What will you do with it? Nothing? \"\n   \"Pardon me, but I do not have time to mold something that will end \"\n   \"up in the trash can.\") \nELSEIF (CheckFlag(__QUEST_FLAG_DEATH_JESTER_DONE) == 1)\n   Conversation\n   INTL( 5741, \"I need 10 units of wax and a small fee of 1000 gold pieces for \"\n   \"the work involved if you want a small apple made of wax. Does \"\n   \"that sound fair enough for you?\")\n   SetYesNo(APPLEWAX) \nELSE\n   Conversation\n   INTL( 5742, \"You want me to mold you an apple made of wax? Fine but you'll have \"\n   \"to do something for me. I want you to get us rid of the horrible \"\n   \"\\\"Death\\\" \\\"Jester\\\" who troubles our nights with his dark jests.\")\nENDIF\n\nYES(APPLEWAX)\n\"\"\nIF (CheckItem(__OBJ_WASP_WAX) >= 10)\n   IF (Gold >= 1000)\n      Conversation\n      INTL(\"${npc.cpp.intl.5743}\")\n      FOR(0, 10)\n         TakeItem(__OBJ_WASP_WAX)\n      ENDFOR\n      IF (rnd.roll(dice(1,10)) > 1) \n         Conversation\n         INTL( 5744, \"Done! I've finished the wax apple. Here you go. Beautiful, isn't? I \"\n         \"hope you are satisfied.\")\n         GiveItem(__OBJ_WAX_APPLE)\n         TakeGold(1000)\n      ELSE\n         Conversation\n         INTL( 5745, \"ARGH! #@!$!@#*#@$* I missed the mold again! I'm sorry, my friend, \"\n         \"you'll have to get 10 more units of wax if you want me to try \"\n         \"again to create a beautiful apple of wax.\")\n      ENDIF\n   ELSE\n      Conversation\n      INTL( 5746, \"I am sorry but you do not have the 1000 gold pieces. I cannot \"\n      \"work for free because my time is simply too precious.\")\n   ENDIF\nELSE\n   ;int nWaxUnits = 10 - CheckItem(__OBJ_WASP_WAX);\n   Conversation\n   FORMAT(INTL( 5747, \"You need %u more wax units if you want me to mold you a \"\n          \"nice apple made of wax. Seek the flying Death Stingers \"\n          \"in the forest for they sometimes carry the precious wax \"\n          \"I require.\"), nWaxUnits)\nENDIF\n\nNO(APPLEWAX)\nConversation\nINTL(\"${npc.cpp.intl.5748}\")\n\nYesNoELSE(APPLEWAX)\nConversation\nINTL(\"${npc.cpp.intl.4598}\")\n\nCmdAND(INTL(\"${npc.cpp.intl.9734}\"),INTL(\"${npc.cpp.intl.9735}\")) \nINTL(\"${npc.cpp.intl.10148}\")  \nIF ((CheckItem(__OBJ_WASP_WAX) >= 5) && (Gold >= 5000)) \n\tConversation\n\tINTL( 10149, \" Ah, I see that you already have the five units of \\\"wax\\\" and the required fee in your \"\n\t\"possession. Shall I get started and mold a brand new candle of eternity for you?\") \n\tSetYesNo(CandleOfEternity) \nENDIF \n\nYES(CandleOfEternity) \n\tIF (CheckItem(__OBJ_WASP_WAX) < 5)\n\t\tConversation\n\t\tINTL(\"${npc.cpp.intl.10150}\")\n\tELSEIF (Gold < 5000) \n\t\tConversation\n\t\tINTL( 10151, \"Hey, I'm just trying to help you. If you don't want to pay a measly 5000 gold, then you \"\n\t\t\"should be on your way.\")\t\n\tELSE\n\t\tPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.10152}\")) \t\t\n\t\tConversation\n\t\tINTL(\"${npc.cpp.intl.10154}\") \n\t\t;int nWaxUnits = 5 - CheckItem(__OBJ_WASP_WAX);\n\t\tFOR(0, 5) \n\t\t\tTakeItem(__OBJ_WASP_WAX)\n\t\tENDFOR\n\t\tTakeGold(5000)  \n\t\tGiveItem(__OBJ_CANDLE_OF_ETERNITY) \n\t\tPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.10155}\")) \n\t\tPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.10156}\"))\t\n\t\tIF ((CheckItem(__OBJ_WASP_WAX) < 5) && (Gold < 5000)) \n\t\t\tConversation\n\t\t\tINTL( 10608, \" All done! Hmmm. I see that you enough wax units to make another candle. Do you want \"\n\t\t\t\"me to mold another candle of eternity for only 5000 gold?\")\n\t\t\tSetYesNo(CandleOfEternity) \n\t\tELSE\t\t\n\t\t\tConversation\n\t\t\tINTL(\"${npc.cpp.intl.10157}\") \n\t\tENDIF\n\tENDIF \n\nNO(CandleOfEternity) \n\tConversation\n\tINTL(\"${npc.cpp.intl.8220}\") \n\nYesNoELSE(CandleOfEternity) \n\tConversation\n\tINTL(\"${npc.cpp.intl.10158}\")\n\tSetYesNo(CandleOfEternity)\n\nCommand(INTL(\"${npc.cpp.intl.5038}\"))\nINTL( 5749, \"I am not sure who told you about my special hobby but I do enjoy creating various \"\n\"objects in wax such as candles, fruits, etc.\") \n\nCmdAND( INTL(\"${npc.cpp.intl.5750}\"),INTL(\"${npc.cpp.intl.5751}\"))\nINTL( 5752, \"I have a few of those. It gives an additional protection to its wearear against \"\n\"all spells.\") \n\nCommand2(INTL(\"${npc.cpp.intl.4002}\"),INTL(\"${npc.cpp.intl.4003}\"))\nINTL(\"${npc.cpp.intl.4226}\")\n\nCommand(INTL(\"${npc.cpp.intl.4124}\"))\nINTL(\"${npc.cpp.intl.5753}\") \n\nCommand(INTL(\"${npc.cpp.intl.4884}\"))\nINTL( 5754, \"The king has request some animal skin from you and you need someone to \"\n\"have it tanned? Let me see... hmmm.. I think that Drardos might be \"\n\"the man for the task.\")\n\nCommand(INTL(\"${npc.cpp.intl.4873}\"))\nINTL(\"${npc.cpp.intl.5755}\")\n\nCommand4(INTL(\"${npc.cpp.intl.695}\"),INTL(\"${npc.cpp.intl.696}\"),INTL(\"${npc.cpp.intl.697}\"),INTL(\"${npc.cpp.intl.698}\"))\nINTL(\"${npc.cpp.intl.5756}\")\nBREAK\n\nCommand4(INTL(\"${npc.cpp.intl.518}\"),INTL(\"${npc.cpp.intl.517}\"),INTL(\"${npc.cpp.intl.519}\"),INTL(\"${npc.cpp.intl.521}\"))\nINTL(\"${npc.cpp.intl.5757}\") BREAK\n\nDefault\nINTL(\"${npc.cpp.intl.5758}\")\n\nEndTalk",
        Map.of()));
    out.put("SanctuaryGuardian", new NpcScripts.Entry(
        "SanctuaryGuardian",
        "NPC AddOn/SanctuaryGuardian.cpp",
        "SanctuaryGuardianNPC",
        "InitTalk\n\nBegin\nINTL( 12545, \"The mausoleum beyond leads to the sanctuary of the ancient God of Corruption, Gluriurl. \"\n\"I guard its entrance and only those who speak the \\\"word\\\" \\\"of\\\" \\\"power\\\" are \"\n\"allowed to pass.\") \n\nCmdAND(INTL(\"${npc.cpp.intl.12546}\"),INTL(\"${npc.cpp.intl.10379}\"))\nINTL(\"${npc.cpp.intl.12547}\") \n\nCommand(INTL(\"${npc.cpp.intl.12548}\")) \n\"\"\nIF(CheckFlag(__FLAG_ADDON_STORYLINE_PROGRESS) >= 33)\n\tConversation\n\tINTL( 12549, \"You spoke the word of power and I am therefore instructed to let you pass. \"\n\t\"However, I must first warn you of the dangers you will face. Even though the \"\n\t\"God of Corruption is no more, its dreadful influence can still be felt throughout \"\n\t\"the endless corridors of the tainted sanctuary. You will encounter Gluriurl's \"\n\t\"followers who were once entombed alive and who are still devoted to him, even in \"\n\t\"their unlife. Thus, I must ask you if you still desire access to this foul place?\") \n\tSetYesNo(LetMePass) \t\nELSE\n\tConversation\n\tINTL( 12550, \"Although you indeed spoke the word of power, I do not feel you capable \"\n\t\"of handling what lies beneath in the sanctuary just yet.\")  \nENDIF\n\nYES(LetMePass) \n\tConversation\n\tINTL(\"${npc.cpp.intl.12551}\") \n\tTELEPORT(691,1319,0) \n\tBREAK \n\nNO(LetMePass)\n\tConversation\n\tINTL(\"${npc.cpp.intl.12552}\")\n\t\nYesNoELSE(LetMePass) \n\tConversation\n\tINTL(\"${npc.cpp.intl.12553}\") \n\tSetYesNo(LetMePass) \n\t\nCommand(INTL(\"${npc.cpp.intl.489}\"))\nINTL(\"${npc.cpp.intl.12554}\")\n\nCommand(INTL(\"${npc.cpp.intl.483}\")) \nINTL(\"${npc.cpp.intl.12555}\") \n\nCommand5(INTL(\"${npc.cpp.intl.519}\"), INTL(\"${npc.cpp.intl.518}\"), INTL(\"${npc.cpp.intl.520}\"), INTL(\"${npc.cpp.intl.517}\"), INTL(\"${npc.cpp.intl.521}\"))\nINTL(\"${npc.cpp.intl.12556}\")\nBREAK\n\nCommand(INTL(\"${npc.cpp.intl.3771}\"))\nINTL(\"${npc.cpp.intl.12557}\") \n\nDefault\n\"\" \nIF(rnd.roll(dice(1,2))) \n\tConversation\n\tINTL(\"${npc.cpp.intl.12558}\")\nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.1623}\")\nENDIF \n\nEndTalk",
        Map.ofEntries(
              Map.entry("OnInitialise", "\n\tNPCstructure::OnInitialise( UNIT_FUNC_PARAM );\n\n\tWorldPos wlPos = { 0,0,0 };\n\tself->SetDestination( wlPos );\n\tself->Do( nothing );\n\tself->SetCanMove( FALSE );\n")
          )));
